css:
:root {
  --recipe-title: #0E5B67;
  --recipe-subtitle: #728DA5;
  --recipe-line: #4B7DA6;
  --recipe-arrow: #176A95;
  --recipe-border: #4B83A7;
  --recipe-number: #1C5A6B;
  --recipe-label: #246975;
  --recipe-secondary: #306897;
  --recipe-separator: #C8DAE5;

  --recipe-white: #FFFFFF;
  --recipe-white-soft: #EEF5F8;
  --recipe-panel-top: #DDEAF1;
  --recipe-panel-bottom: #D3E3ED;

  --recipe-dark: #080B09;
  --recipe-danger: #C21D1D;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.recipe-widget {
  width: 100%;
  height: 100%;
  padding: 14px 30px;

  background: transparent;
  color: var(--recipe-label);

  font-family: Arial, Helvetica, sans-serif;

  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.recipe-screen {
  display: grid;
  grid-template-rows:
    100px
    minmax(0, 1fr)
    44px;
  gap: 10px;

  width: 100%;
  height: 100%;
  max-width: 1644px;
  margin-inline: auto;
  min-height: 0;
}

.recipe-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: 56px 34px;
  gap: 10px;
}

.recipe-heading {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 5px;
  min-width: 0;
}

.recipe-subtitle {
  color: var(--recipe-subtitle); font-size: 14px; line-height: 1.3; white-space: nowrap;
}

.recipe-title {
  color: var(--recipe-title);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.recipe-counter {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 11px;
}

.recipe-counter-text {
  color: var(--recipe-subtitle);
  font-size: 14px;
  line-height: 18.2px;
}

.recipe-toolbar {
  grid-column: 1 / -1;

  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 16px;
}

.recipe-toolbar-left {
  display: flex;
  align-items: stretch;
  gap: 8px;
}

.recipe-action {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  height: 34px;
  padding: 0 14px;

  border: 1px solid var(--recipe-border);
  border-radius: 6px;
  background: linear-gradient(
    180deg,
    var(--recipe-white),
    var(--recipe-white-soft)
  );

  color: var(--recipe-number);
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;

  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.recipe-action svg {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;

  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.recipe-action--primary {
  border-color: var(--recipe-title);
  background: var(--recipe-title);
  color: #FFFFFF;
  box-shadow: none;
}

.recipe-action--danger {
  color: var(--recipe-danger);
}

.recipe-status {
  display: flex; flex: 1; min-width: 0; align-items: center;
  justify-content: flex-start; gap: 22px; padding: 0 4px;
  background: transparent; border: 0;
}
.recipe-status-left {
  display: flex; flex-direction: column; justify-content: center; gap: 2px; min-width: 0;
}
.recipe-status-label { color: var(--recipe-secondary); font-size: 11px; font-weight: 700; line-height: 11px; }
.recipe-status-name { color: var(--recipe-number); font-size: 15px; font-weight: 700; line-height: 17px; white-space: nowrap; }
.recipe-status-summary { display: flex; align-items: center; gap: 10px; min-width: 0; }
.recipe-status-badge {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 3px 9px; border-radius: 4px;
  background: #D3E1E7; color: #3D5B6B;
  font-size: 12px; font-weight: 700; line-height: 14px; white-space: nowrap;
}

/* Campos originales: catorce a la izquierda y diez a la derecha. */
.nominal-layout {
  display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 42px;
  min-width: 0; min-height: 0; padding: 8px 18px;
}
.nominal-column {
  display: grid; grid-template-rows: repeat(14,minmax(0,1fr)); gap: 5px;
  min-width: 0; min-height: 0;
}
.nominal-row {
  display: grid; grid-template-columns: minmax(0, calc((100% - 49px) * 0.4117647059)) minmax(0,1fr) 78px minmax(0,1fr);
  column-gap: 5px; align-items: center; min-width: 0; min-height: 0;
}
.nominal-label {
  display: flex; align-items: center; align-self: center;
  height: min(34px,100%); min-height: 0; padding-top: 2px;
  color: var(--recipe-label); font-size: 18px; font-weight: 700;
  line-height: 1; white-space: nowrap;
}
.nominal-unit { width: 100%; height: 100%; min-width: 0; }

.recipe-value {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: min(34px, 100%);
  min-height: 0;
}

.recipe-value--editable {
  border: 1px solid var(--recipe-border);
  border-radius: 2px;
  background: linear-gradient(
    180deg,
    var(--recipe-white),
    var(--recipe-white-soft)
  );

  box-shadow: inset 0 1px 2px rgba(28, 90, 107, 0.05);
}

.recipe-value--applied {
  border: 2px solid #829795;
  border-radius: 2px;
  background: var(--recipe-dark);

  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.35);
}

.recipe-footer {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 20px; padding-top: 8px;
  border-top: 1px solid var(--recipe-separator);
  color: var(--recipe-subtitle); font-size: 13px; line-height: 14.4px;
}

.recipe-apply-group {
  display: flex;
  align-items: center;
  gap: 14px;
}

.recipe-apply-group .recipe-action {
  height: 32px;
  padding-inline: 16px;
}

.recipe-apply-description {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
}

.recipe-apply-title {
  color: var(--recipe-number);
  font-size: 14px;
  font-weight: 700;
  line-height: 15.6px;
}

.recipe-legend {
  display: flex;
  align-items: center;
  gap: 18px;
}

.recipe-legend-item {
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
}

.recipe-legend-square {
  display: block;
  width: 12px;
  height: 12px;
  flex: 0 0 auto;

  border: 1px solid var(--recipe-border);
  background: #FFFFFF;
}

.recipe-legend-square--dark {
  background: var(--recipe-dark);
}


/* Segunda aparición de Salida Secador: resaltado original. */
.nominal-row-alert .nominal-label { color: var(--recipe-danger); }

