"use strict";
(function () {
  const DEFAULT_TITLE = "LÍNEA 3 / RECETA DE TOLERANCIAS";
  const DEFAULT_SUBTITLE = "Configuración de las tolerancias de los valores nominales del proceso";
  let latestWidget = null;
  const LEFT_LABELS = [
    "Cubas 1 y 12",
    "Cubas 13 y 14",
    "Cubas 2 a la 11",
    "Agua a Cubas",
    "Flujo Preparación",
    "Conductividad",
    "Vapor Secador",
    "Calef. Rizadoras",
    "Cajas Rizadoras",
    "Tanque Dosificador",
    "Tanque de Mezcla",
    "Vapor al Secador",
    "Rodillos Rizadoras",
    "Flujo Tq. Dosificador"
  ];
  const RIGHT_LABELS = [
    "Pre-Estiramiento",
    "Entrada Estiramiento",
    "Salida Estiramiento",
    "Preparación",
    "Secador Zonas 1-5",
    "Entrada Lavadora",
    "Salida Lavadora",
    "Salida Secador",
    "Salida Secador",
    "Corriente Motor DC"
  ];
  function make(tag, className, parent, text) {
    const el = document.createElement(tag); el.className = className;
    if (text !== undefined) el.textContent = text;
    parent.appendChild(el); return el;
  }
  function fitHeader() {
    [[".recipe-title",28],[".recipe-subtitle",14]].forEach(function(entry) {
      const el = document.querySelector(entry[0]); if (!el || el.hidden) return;
      el.style.fontSize = entry[1]+"px";
      if (el.clientWidth > 0 && el.scrollWidth > el.clientWidth)
        el.style.fontSize = (entry[1]*el.clientWidth/el.scrollWidth)+"px";
    });
  }
  function updateHeader(widget) {
    const title = document.querySelector(".recipe-title");
    const subtitle = document.querySelector(".recipe-subtitle");
    if (!title || !subtitle) return;
    const name = widget && typeof widget.name === "string" ? widget.name.trim() : "";
    const split = name.indexOf("//");
    title.textContent = (split < 0 ? name : name.slice(0,split)).trim() || DEFAULT_TITLE;
    subtitle.textContent = split < 0 ? DEFAULT_SUBTITLE : name.slice(split+2).trim();
    subtitle.hidden = subtitle.textContent === "";
    fitHeader();
  }
  function buildWidget() {
    const left = document.getElementById("nominal-left");
    const right = document.getElementById("nominal-right");
    if (!left || !right) return;
    [[left,LEFT_LABELS],[right,RIGHT_LABELS]].forEach(function(entry) {
      entry[0].replaceChildren();
      entry[1].forEach(function(label, index) {
        const row = make("div",entry[0] === right && index === 8 ? "nominal-row nominal-row-alert" : "nominal-row",entry[0]);
        make("span","nominal-label",row,label);
        make("div","recipe-value recipe-value--editable",row).setAttribute("aria-hidden","true");
        make("div","nominal-unit",row).setAttribute("aria-hidden","true");
        make("div","recipe-value recipe-value--applied",row).setAttribute("aria-hidden","true");
      });
    });
    updateHeader(latestWidget || window.WIDGET || null);
    if (typeof ResizeObserver !== "undefined") {
      new ResizeObserver(fitHeader).observe(document.querySelector(".recipe-heading"));
    }
  }
  // NOMBRE: Título//Subtítulo. Widget visual: no recibe tags ni ejecuta acciones.
  window.onWidgetUpdate = function(widget) { latestWidget=widget; updateHeader(widget); };
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded",buildWidget,{once:true});
  else buildWidget();
})();
